-- 从 bridge_type_output.xlsx 导入重庆桥梁基础清单（共 323 条）
-- 坐标按 GCJ-02 原值保存；IMP-0323 原始纬度异常，保留桥梁并待核验。

VALUES ('CQ-IMPORT','重庆市待补充路线','待补充');

VALUES ('unknown','未确定桥型');

ON DUPLICATE KEY UPDATE
  bridge_type_code=VALUES(bridge_type_code),
  bridge_name=VALUES(bridge_name),
  location_address=VALUES(location_address),
  longitude=VALUES(longitude),
  latitude=VALUES(latitude),
  coordinate_source=VALUES(coordinate_source),
  raw_longitude=VALUES(raw_longitude),
  raw_latitude=VALUES(raw_latitude),
  notes=VALUES(notes),
  update_time=CURRENT_TIMESTAMP;
